def parse_fred_frame(frame):
    """统一为日期索引、数值列；FRED 的 '.' 与空值视为缺失。"""
    out = frame.copy()
    out.index = pd.to_datetime(out.index).normalize().as_unit("ns")
    out.index.name = "date"
    out = out.apply(pd.to_numeric, errors="coerce")
    out = out[~out.index.duplicated(keep="last")].sort_index()
    return out[[c for c in FRED_SERIES if c in out.columns]]


def read_fred_upload(files):
    """接受本程序导出的宽表 CSV(.gz)，或 FRED 网页"Download CSV"得到的单序列文件（可多选）。"""
    parts = []
    for item in files:
        data = item.getvalue() if hasattr(item, "getvalue") else item
        comp = "gzip" if data[:2] == b"\x1f\x8b" else None
        table = pd.read_csv(BytesIO(data), compression=comp)
        table = table.set_index(table.columns[0])
        parts.append(parse_fred_frame(table))
    if not parts:
        raise ValueError("没有可读取的 FRED 文件。")
    merged = pd.concat(parts, axis=1)
    return merged.T.groupby(level=0).last().T


