def _fred_one(sid):
    """单个序列：两个官方地址各试一次，短超时，失败抛出异常。"""
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
               "(KHTML, like Gecko) Chrome/124.0 Safari/537.36", "Accept": "text/csv,*/*"}
    last = None
    getters = []
    try:
        from curl_cffi import requests as _creq
        getters.append(lambda u: _creq.get(u, impersonate="chrome", timeout=15,
                                           **({"verify": ASCII_CACERT} if ASCII_CACERT else {})))
    except Exception:
        pass
    getters.append(lambda u: requests.get(u, headers=headers, timeout=(5, 12)))
    attempts = [(g, u) for g in getters for u in (f"https://fred.stlouisfed.org/graph/fredgraph.csv?id={sid}",
                                                   f"https://fred.stlouisfed.org/series/{sid}/downloaddata/{sid}.csv")]
    for getter, url in attempts:
        try:
            resp = getter(url)
            resp.raise_for_status()
            table = pd.read_csv(BytesIO(resp.content))
            values = parse_fred_frame(table.set_index(table.columns[0]))
            if sid not in values or values[sid].notna().sum() < 10:
                raise ValueError("返回内容不是有效的FRED序列")
            return values[sid]
        except Exception as exc:
            last = exc
    raise last


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_fred_data(refresh_bucket=None, budget_seconds=45):
    """并行下载全部 FRED 序列，总耗时上限 budget_seconds；超时或任一失败即整体回退。
    返回 {"data","error","retrieved"}；失败结果同样缓存1小时，FRED 不可达时不会每次刷新都等待。"""
    from concurrent.futures import ThreadPoolExecutor, wait as _wait
    pool = ThreadPoolExecutor(max_workers=3)  # FRED 对并发敏感，限3路
    futures = {pool.submit(_fred_one, sid): sid for sid in FRED_SERIES}
    done, pending = _wait(futures, timeout=budget_seconds)
    pool.shutdown(wait=False, cancel_futures=True)
    if pending:
        names = ", ".join(sorted(futures[f] for f in pending))
        return {"data": None, "error": f"{budget_seconds}秒内未完成（{names}）", "retrieved": None}
    series = {}
    for fut in done:
        sid = futures[fut]
        if fut.exception() is not None:
            exc = fut.exception()
            return {"data": None, "error": f"{sid}: {type(exc).__name__} {exc}"[:300], "retrieved": None}
        series[sid] = fut.result()
    return {"data": pd.concat(series, axis=1)[list(FRED_SERIES)], "error": None,
            "retrieved": datetime.now(timezone.utc).isoformat()}


def load_fred_inputs(uploads=None):
    """FRED 数据优先级：用户上传 > 在线下载 > 服务器保存的快照 > 文件内置快照。
    任何来源都与内置快照合并，以保留 FRED 只提供近3年的 ICE 利差历史。返回 (数据, 来源说明, 提示)。"""
    base = embedded_fred()
    saved = newest_fred_snapshot()
    if saved is not None:
        base = merge_fred(saved[0], base)
    if uploads:
        return merge_fred(read_fred_upload(uploads), base), "用户上传的FRED文件", ""
    bucket = int(datetime.now(timezone.utc).timestamp() // 3600)
    result = fetch_fred_data(bucket)
    if result["data"] is not None:
        fred = merge_fred(result["data"], base)
        note = ""
        if USER_CONFIG["SAVE_LOCAL_BACKUP"]:
            try:
                save_fred_snapshot(fred)
            except OSError as exc:
                note = f"FRED数据已获取，但本地快照写入失败：{exc}"
        stamp = pd.Timestamp(result["retrieved"]).tz_convert("Asia/Tokyo")
        return fred, f"FRED在线（{stamp:%m-%d %H:%M} 日本时间获取，缓存1小时）", note
    label = f"服务器快照 {saved[1]}" if saved is not None else "文件内置FRED快照"
    return base, label, f"FRED在线下载失败，资金面使用{label}（截至 {fred_last_date(base):%Y-%m-%d}）。原因：{result['error']}"


def fred_last_date(fred):
    """实际最后观测日（不超过今天）；周度标签不会冒充未来日期。"""
    obs = fred.dropna(how="all")
    obs = obs.loc[obs.index <= pd.Timestamp.now().normalize()]
    return obs.index[-1]


def save_fred_snapshot(fred):
    """保存原始观测（不做周度重采样），避免把未结束的周标成周五。"""
    FRED_DIR.mkdir(parents=True, exist_ok=True)
    fred = fred.loc[fred.index <= pd.Timestamp.now().normalize()]
    payload = fred.to_csv(date_format="%Y-%m-%d").encode("utf-8")
    import gzip
    target = FRED_DIR / f"fred_daily_{fred_last_date(fred):%Y%m%d}.csv.gz"
    if not target.exists():
        target.write_bytes(gzip.compress(payload))
    return target


def newest_fred_snapshot():
    if not FRED_DIR.exists():
        return None
    for path in sorted(FRED_DIR.glob("fred_daily_*.csv.gz"), key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            return read_fred_upload([path.read_bytes()]), path.name
        except Exception:
            continue
    return None


def merge_fred(primary, base):
    """新数据优先；新数据没有的历史（例如 ICE 超出 FRED 3年窗口的部分）由旧快照保留。"""
    if base is None:
        return primary
    cols = list(dict.fromkeys(list(primary.columns) + list(base.columns)))
    primary = primary.reindex(columns=cols)
    base = base.reindex(columns=cols)
    # 每个序列：新数据覆盖其起点之后的全部日期；旧快照只补新数据起点之前的历史，避免周度行混入日度数据
    for col in cols:
        first = primary[col].first_valid_index()
        if first is not None:
            base.loc[base.index >= first, col] = np.nan
    out = primary.combine_first(base)
    return out.loc[out.notna().any(axis=1)]


def capital_factors(fred, calendar):
    """三项资金指标的周度计算，再按发布滞后映射到行情交易日。返回 (日度因子, 周度明细)。"""
    weekly = fred.resample("W-FRI").mean()
    # 只保留已结束的周：最后一周若尚未到周五则丢弃，避免不完整周均值
    weekly = weekly.loc[weekly.index <= pd.Timestamp.now().normalize()]
    w = pd.DataFrame(index=weekly.index)
    rrp = weekly["RRPONTSYD"].where(weekly.index >= "2003-03-01").fillna(0.0)  # 无操作的周记为0
    bs = weekly[["WALCL", "WDTGAL"]].ffill(limit=2)
    w["净流动性(十亿美元)"] = (bs["WALCL"] - bs["WDTGAL"]) / 1000 - rrp
    w["联邦基金−3月国债(%)"] = weekly["DFF"] - weekly["DTB3"]
    for target, (const, betas) in SPREAD_SPLICE.items():
        est = const + sum(weekly[k] * b for k, b in betas.items())
        w[target + "(含回推)"] = weekly[target].combine_first(est)
        w[target + "为回推值"] = weekly[target].isna() & est.notna()
    pct = lambda s: s.rolling(CAPITAL_WINDOW_WEEKS, min_periods=CAPITAL_WINDOW_WEEKS).rank(pct=True) * 100
    w["P5"] = pct(w["净流动性(十亿美元)"])
    w["P6"] = pct(w["联邦基金−3月国债(%)"])
    w["P7"] = 100 - (pct(w["BAMLH0A0HYM2(含回推)"]) + pct(w["BAMLC0A0CM(含回推)"])) / 2
    w["可用日期"] = w.index + pd.Timedelta(days=FRED_RELEASE_LAG_DAYS)
    avail = w.set_index("可用日期")[["P5", "P6", "P7"]].dropna(how="all")
    daily = avail.reindex(avail.index.union(calendar)).ffill(limit=15).reindex(calendar)
    # 超过约3周未更新则视为缺失，不让过期数据冒充最新
    return daily, w


def calculate_indices_v4(raw, fred, smooth_days=None):
    """V4：情绪四项沿用原定义；资金三项为 FRED 重建；总分=7项等权+人工修正。"""
    base = calculate_indices(raw, p6_method=USER_CONFIG["P6_METHOD"])
    calendar = base.index
    daily, weekly = capital_factors(fred, calendar)
    df = base.copy()
    df["旧P5"], df["旧P6"] = df.pop("P5"), df.pop("P6")
    df["旧版完整指数"] = df.pop("完整指数")
    df["旧版综合资金指标"] = base["综合资金指标"]
    for k in ["P5", "P6", "P7"]:
        df[k] = daily[k]
    factors = df[list(NEW_FACTOR_NAMES)]
    smooth = USER_CONFIG["TOTAL_SMOOTH_DAYS"] if smooth_days is None else smooth_days
    raw_total = factors.mean(axis=1, skipna=False)
    if smooth and smooth > 1:
        raw_total = raw_total.rolling(int(smooth), min_periods=int(smooth)).mean()
    full = (raw_total + USER_CONFIG["V4_BIAS_POINTS"]).clip(0, 100)
    senti = factors[["P1", "P2", "P3", "P4"]]
    capital = factors[["P5", "P6", "P7"]]
    # 早期参考：情绪与资金各至少一项可用时，按可用项等权平均；不与完整期拼接成同一口径
    ref_raw = factors.mean(axis=1)
    if smooth and smooth > 1:
        ref_raw = ref_raw.rolling(int(smooth), min_periods=int(smooth)).mean()
    ok_ref = senti.notna().any(axis=1) & capital.notna().any(axis=1)
    reference = (ref_raw + USER_CONFIG["V4_BIAS_POINTS"]).clip(0, 100).where(ok_ref)
    first_full = full.first_valid_index()
    if first_full is not None:
        reference = reference.where(reference.index < first_full)
    df["完整指数"] = full
    df["完整指数（不含人工修正）"] = (raw_total).clip(0, 100)
    df["早期参考指数"] = reference
    df["总泡沫指数"] = full.combine_first(reference)
    df["数据类型"] = np.select([full.notna(), reference.notna()], ["完整模型", "早期参考"], default="不可计算")
    df["综合情绪指标"] = senti.mean(axis=1, skipna=False).where(full.notna(), senti.mean(axis=1).where(reference.notna()))
    df["综合资金指标"] = capital.mean(axis=1, skipna=False).where(full.notna(), capital.mean(axis=1).where(reference.notna()))
    df["有效指标数"] = factors.notna().sum(axis=1)
    df["原权重覆盖率"] = factors.notna().mean(axis=1) * 100
    df["平滑期最低覆盖率"] = df["原权重覆盖率"].rolling(max(int(smooth or 1), 1)).min()
    df["参与指标"] = factors.notna().apply(lambda row: ", ".join(row.index[row]), axis=1)
    return df



def percentile_summary(df):
    """Always use full history through the same latest complete date; never view filters."""
    full = df["完整指数"].dropna()
    if full.empty:
        return None
    asof = full.index[-1]
    global_values = df.loc[:asof, "总泡沫指数"].dropna()
    val = float(full.iloc[-1])
    return {"asof": asof, "value": val, "full": full, "global": global_values,
            "full_pct": float(percentileofscore(full, val, kind="rank")),
            "global_pct": float(percentileofscore(global_values, val, kind="rank"))}


@st.cache_data(ttl=3600, show_spinner=False)
def run_backtest(df, zones=None):
    """Complete-model signal dates only; future returns use the unfiltered QQQ calendar.
    收益周期按真实交易日偏移，不能先删去缺失信号日再计算持有周期。
    """
    results = []
    for lo, hi, label, color in (zones or ZONES):
        mask = df["完整指数"].ge(lo) & df["完整指数"].lt(hi)
        row = {"区间": label, "信号天数": int(mask.sum()), "color": color}
        for name, days in PERIODS:
            rets = ((df.QQQ.shift(-days) / df.QQQ - 1) * 100).loc[mask].dropna()
            row.update({f"{name}_avg": rets.mean(), f"{name}_median": rets.median(),
                        f"{name}_win": (rets > 0).mean() * 100 if len(rets) else np.nan,
                        f"{name}_n": len(rets)})
        results.append(row)
    return results


def index_color(value, ret=0, zones=None):
    if pd.isna(value): return C_MUTED
    zones = zones or ZONES
    # Same [lo, hi) boundary rule as the backtest.
    for lo, hi, _, color in zones:
        if lo <= value < hi:
            return "#FF9F0A" if zones is ZONES and lo == 45 and ret >= 0 else color
    return C_MUTED


def period_text(values):
    values = values.dropna()
    return "暂无有效数据" if values.empty else f"{values.index[0]:%Y-%m-%d} — {values.index[-1]:%Y-%m-%d} · {len(values):,} 个交易日"


def plot_index(frame, show_legacy=False, zones=None):
    zones = zones or ZONES
    fig = make_subplots(specs=[[{"secondary_y": True}]])
    for lo, hi, label, color in zones:
        fig.add_hrect(y0=lo, y1=min(hi, 100), fillcolor=color, opacity=.06,
                      line_width=0, layer="below", secondary_y=False)
        if zones is not ZONES:
            name = label.split(" ", 1)[1].split(" (")[0] if " " in label else label
            fig.add_annotation(x=0.004, xref="paper", xanchor="left", y=(lo + min(hi, 100)) / 2, yref="y",
                               text=name, showarrow=False, font=dict(size=11, color=color), opacity=.8,
                               bgcolor="rgba(10,13,19,.55)", borderpad=2)
    q = frame.QQQ.dropna()
    fig.add_trace(go.Scatter(x=frame.index, y=frame.QQQ, name="QQQ（右轴）", fill="tozeroy",
        fillcolor="rgba(120,140,170,.07)", line=dict(color="rgba(180,192,212,.38)", width=1.1),
        hovertemplate="QQQ: $%{y:.2f}<extra></extra>"), secondary_y=True)
    # Mask traces without dropping rows so unavailable periods are never connected.
    colors = pd.Series([index_color(v,r,zones) for v,r in zip(frame["完整指数"], frame.QQQ_1w_ret)], index=frame.index)
    # Connected segments share their boundary point; null values explicitly break lines.
    for color in colors.unique():
        mask = colors.eq(color) & frame["完整指数"].notna()
        y = frame["完整指数"].where(mask | mask.shift(1, fill_value=False))
        fig.add_trace(go.Scatter(x=frame.index, y=y, mode="lines", connectgaps=False,
            line=dict(color=color, width=2.6), hoverinfo="skip", showlegend=False), secondary_y=False)
    fig.add_trace(go.Scatter(x=frame.index, y=frame["完整指数"], mode="lines", name="完整模型",
        line=dict(color="rgba(0,0,0,0)", width=.1), connectgaps=False,
        hovertemplate="完整指数: %{y:.2f}<extra></extra>"), secondary_y=False)
    fig.add_trace(go.Scatter(x=frame.index, y=frame["早期参考指数"], mode="lines", name="早期参考（非完整模型）",
        line=dict(color="#a4a8b5", width=2, dash="dash"), connectgaps=False,
        customdata=frame[["有效指标数", "原权重覆盖率", "参与指标"]].to_numpy(),
        hovertemplate="早期参考: %{y:.2f}<br>当日有效指标: %{customdata[0]} 项"
                      "<br>原权重覆盖: %{customdata[1]:.1f}%<br>%{customdata[2]}<extra></extra>"), secondary_y=False)
    if show_legacy and "旧版总泡沫指数" in frame:
        fig.add_trace(go.Scatter(x=frame.index, y=frame["旧版总泡沫指数"],
            name="旧版对照", mode="lines", connectgaps=False,
            line=dict(color="#FF9F0A", width=1.6, dash="dash"),
            hovertemplate="旧版指数: %{y:.2f}<extra></extra>"), secondary_y=False)
    layout = dark_layout(height=540)
    layout.update(showlegend=True, legend=dict(orientation="h", y=1.08, x=0, font=dict(size=12, color=C_MUTED)))
    fig.update_layout(**layout)
    fig.update_yaxes(range=[0,100], title_text="泡沫指数", secondary_y=False)
    if len(q):
        pad = (q.max() - q.min()) * .08
        fig.update_yaxes(range=[q.min() - pad, q.max() + pad], secondary_y=True)
    fig.update_yaxes(title_text="QQQ 复权价格", showgrid=False, secondary_y=True,
                     tickfont=dict(color=C_MUTED, size=11, family="JetBrains Mono, Consolas, monospace"))
    return fig


