def render_network_diagnostics():
    """逐项测试数据源，显示完整错误，便于定位本机/云端网络问题。只读访问。"""
    import time, traceback, certifi
    rows = []

    def run(name, fn):
        t = time.time()
        try:
            detail = fn()
            rows.append({"测试": name, "结果": "成功", "耗时秒": round(time.time() - t, 1), "详情": str(detail)[:300]})
        except Exception as exc:
            rows.append({"测试": name, "结果": "失败", "耗时秒": round(time.time() - t, 1),
                         "详情": (type(exc).__name__ + ": " + str(exc))[:300],
                         "traceback": traceback.format_exc()[-1500:]})

    def yf_test():
        d = yf.download(["QQQ"], period="5d", progress=False, threads=False, auto_adjust=True)
        return f"{len(d)} 行"
    def chart_test():
        d = _yahoo_chart("QQQ", "2026-10-01")
        return f"{len(d)} 行，最后 {d.index[-1]:%Y-%m-%d} 收盘 {d['Close'].iloc[-1]:.2f}"
    def combined_test():
        d = yahoo_download(["QQQ", "^VIX", "IPO"], start="2026-10-01")
        return f"{d.shape}，来源：{d.attrs.get('source_note', 'yfinance')}"
    def fred_curl():
        from curl_cffi import requests as creq
        r = creq.get("https://fred.stlouisfed.org/graph/fredgraph.csv?id=DFF", impersonate="chrome", timeout=15,
                     **({"verify": ASCII_CACERT} if ASCII_CACERT else {}))
        return f"HTTP {r.status_code}, {len(r.content)} 字节"
    def fred_requests():
        r = requests.get("https://fred.stlouisfed.org/graph/fredgraph.csv?id=DFF", timeout=(5, 12),
                         headers={"User-Agent": "Mozilla/5.0"})
        return f"HTTP {r.status_code}, {len(r.content)} 字节"
    def eastmoney():
        return f"{len(fetch_fund_nav('016701'))} 个净值日"
    for name, fn in [("yfinance 下载 QQQ", yf_test), ("Yahoo chart 接口", chart_test),
                     ("组合下载（yfinance→回退）", combined_test), ("FRED（curl_cffi 伪装Chrome）", fred_curl),
                     ("FRED（requests）", fred_requests), ("天天基金 016701", eastmoney)]:
        run(name, fn)
    st.write(f"certifi 证书：`{certifi.where()}`；curl 使用：`{ASCII_CACERT}`；yfinance {getattr(yf, '__version__', '?')}")
    st.dataframe(pd.DataFrame(rows).drop(columns=["traceback"], errors="ignore"), hide_index=True, width="stretch")
    for r in rows:
        if r.get("traceback"):
            with st.expander(f"{r['测试']} 的完整错误"):
                st.code(r["traceback"])


def render_backtest(df, zones=None):
    st.subheader("历史回测：仅使用完整模型的信号")
    full = df["完整指数"].dropna()
    if full.empty:
        st.info("暂无完整模型历史，不能开展正式回测。")
        return
    st.caption(period_text(full) + "。早期参考段不参与；逐日信号存在重叠，样本并非独立交易。")
    results = run_backtest(df, tuple(zones or ZONES))
    rows=[]
    for r in results:
        row={"区间":r["区间"], "信号天数":r["信号天数"]}
        for p,_ in PERIODS:
            row[f"{p}均收益(%)"] = r[f"{p}_avg"]
            row[f"{p}胜率(%)"] = r[f"{p}_win"]
            row[f"{p}有效样本"] = r[f"{p}_n"]
        rows.append(row)
    st.dataframe(pd.DataFrame(rows).round(2), hide_index=True, width="stretch")
    period=st.selectbox("持有周期",[p for p,_ in PERIODS],index=2)
    fig=go.Figure()
    fig.add_trace(go.Bar(x=[r["区间"] for r in results],y=[r[f"{period}_avg"] for r in results],name="均值",marker_color=C_BLUE))
    fig.add_trace(go.Scatter(x=[r["区间"] for r in results],y=[r[f"{period}_median"] for r in results],name="中位数",mode="markers",marker=dict(color="#F7DC6F",size=12,symbol="diamond")))
    fig.update_layout(**dark_layout(height=400,y_title="收益率 (%)"))
    fig.update_layout(showlegend=True)
    st.plotly_chart(fig,width="stretch")
    win=go.Figure(go.Bar(x=[r["区间"] for r in results],y=[r[f"{period}_win"] for r in results],marker_color=C_BLUE))
    win.add_hline(y=50,line_dash="dash",line_color="#FF9F0A")
    win.update_layout(**dark_layout(height=320,y_range=[0,100],y_title="正收益胜率 (%)"))
    st.plotly_chart(win,width="stretch")
    multi=go.Figure()
    for p,_ in PERIODS:
        multi.add_trace(go.Scatter(x=[r["区间"] for r in results],y=[r[f"{p}_avg"] for r in results],name=p,mode="lines+markers"))
    multi.update_layout(**dark_layout(height=360,y_title="平均收益率 (%)"))
    multi.update_layout(showlegend=True)
    st.plotly_chart(multi,width="stretch")
    st.caption("采用当日收盘指数与收盘价的条件收益统计，未模拟可执行成交、成本或资金管理；历史收益不代表未来表现。")

