def zone_of(value, zones):
    for lo, hi, label, color in zones:
        if lo <= value < hi:
            return label, color
    return "—", C_MUTED


def module_keys(model, module):
    if module == "情绪面":
        return MODULES["情绪面"]
    return MODULES["资金面_v4" if model == "v4" else "资金面_legacy"]


