def composition_table(df, stats, factor_names, model):
    if not stats:
        return pd.DataFrame()
    asof = stats["asof"]
    rows = []

    def value_at(col, days=0):
        series = df[col].loc[:asof - pd.Timedelta(days=days)].dropna()
        return float(series.iloc[-1]) if len(series) else np.nan

    for module, field in [("情绪面", "综合情绪指标"), ("资金面", "综合资金指标")]:
        keys = module_keys(model, module)
        weight = (len(keys) / 7 * 100) if model == "v4" else (200 / 3 if module == "情绪面" else 100 / 3)
        now = value_at(field)
        rows.append({"模块": module, "指标": f"【{module}合计】", "当前": now,
                     "1周变化": now - value_at(field, 7), "1月变化": now - value_at(field, 30), "权重": weight,
                     "数据来源": "", "含义": "模块内各项平均" if model == "v4" else "旧版模块合成"})
        for key in keys:
            docs = FACTOR_DOCS[key] if model == "v4" or key not in LEGACY_DOCS else LEGACY_DOCS[key]
            now = value_at(key)
            rows.append({"模块": module, "指标": f"{key} {factor_names[key]}", "当前": now,
                         "1周变化": now - value_at(key, 7), "1月变化": now - value_at(key, 30),
                         "权重": (100 / 7) if model == "v4" else LEGACY_WEIGHTS[key] * 100,
                         "数据来源": docs[0], "含义": docs[2]})
    return pd.DataFrame(rows)


