def render_zone_explainer(df, stats, zones, model):
    left, right = st.columns([1.2, 1])
    with left:
        st.markdown("#### 历史分布")
        if stats:
            hist = go.Figure()
            hist.add_trace(go.Histogram(x=stats["full"], name="完整模型", xbins=dict(start=0, end=100, size=2),
                                        marker_color=C_BLUE, opacity=.8))
            for lo, hi, _, color in zones:
                hist.add_vrect(x0=lo, x1=min(hi, 100), fillcolor=color, opacity=.07, line_width=0)
            hist.add_vline(x=stats["value"], line_color="#ffffff", annotation_text=f"当前 {stats['value']:.1f}")
            hist.update_layout(**dark_layout(height=330, y_title="交易日数"))
            hist.update_xaxes(range=[0, 100], title="指数值")
            st.plotly_chart(hist, width="stretch")
    with right:
        st.markdown("#### 评级区间")
        table = pd.DataFrame([{"区间": label, "下限": lo, "上限": min(hi, 100)} for lo, hi, label, _ in zones])
        if stats:
            full = stats["full"]
            table["历史天数占比%"] = [round(full.ge(lo).mul(full.lt(hi)).mean() * 100, 1) for lo, hi, _, _ in zones]
        st.dataframe(table, hide_index=True, width="stretch")
    if model == "v4" and stats:
        st.markdown("#### 区间锚点：历次美股底部与阶段顶部时的指数读数")
        full = stats["full"]
        rows = []
        for kind, day, name in V4_ANCHORS:
            d = pd.Timestamp(day)
            if d < full.index[0] or d > full.index[-1]:
                continue
            window = full.loc[d - pd.Timedelta(days=21):d + pd.Timedelta(days=21)]
            rows.append({"类型": kind, "事件": name, "日期": day, "当日读数": round(float(full.asof(d)), 1),
                         "前后3周最低": round(float(window.min()), 1), "前后3周最高": round(float(window.max()), 1)})
        st.dataframe(pd.DataFrame(rows), hide_index=True, width="stretch")
        st.caption("划分依据：2018、2020、2022 三次主要熊市底部的读数都在约26–32，2020、2025 底部附近在 36–40；"
                   "2026年3月底部约41；2021年11月泡沫顶约67，2024年7月、2025年2月顶部约71–75。区间是对历史读数的描述性归纳，"
                   "完整期只有2017年以来一个市场周期，样本有限，不构成买卖规则。")
    elif model != "v4":
        st.caption("旧版评级区间沿用原应用设定（含 +15 修正后的读数）。")


