def completed_market_rows(raw, now=None):
    """Exclude unfinished sessions; allow today's bar after 16:30 New York.
    纽约16:30后才接受当日日线；提前收市日同样保守等待，不把盘中数据当收盘。
    """
    now = pd.Timestamp.now(tz='America/New_York') if now is None else pd.Timestamp(now).tz_convert('America/New_York')
    cutoff = now.normalize().tz_localize(None)
    accept_today = now.hour * 60 + now.minute >= 16 * 60 + 30
    return raw.loc[raw.index <= cutoff] if accept_today else raw.loc[raw.index < cutoff]


def live_market_bucket(now=None):
    stamp = datetime.now(timezone.utc).timestamp() if now is None else pd.Timestamp(now).timestamp()
    return int(stamp // USER_CONFIG['CACHE_SECONDS'])


def load_live_market():
    return fetch_market_data(live_market_bucket())


