def install_market_auto_refresh():
    st.sidebar.caption('在线模式：打开或操作页面时获取最新行情（缓存最多5分钟）；页面保持打开时每5分钟检查。网页关闭后不运行后台任务。')
    if not hasattr(st, 'fragment'):
        st.sidebar.caption('当前Streamlit版本无定时片段，请重新打开页面或点击立即更新获取新数据。')
        return
    @st.fragment(run_every=60)
    def heartbeat():
        bucket = live_market_bucket()
        prior = st.session_state.get('_market_heartbeat_bucket', bucket)
        st.session_state['_market_heartbeat_bucket'] = bucket
        if bucket != prior:
            page = st.session_state.get('main_page', '综合指数看板')
            key = 'preview_market_live_v2' if page == '美投对照' else 'market_source_live_v2'
            online = st.session_state.get(key, '在线行情（自动更新）') not in ['内置核查快照', '固定核查快照']
            if page not in ('主动基金筛选', '持仓基金对比') and online:
                st.rerun(scope='app')
    heartbeat()


@st.cache_data(ttl=USER_CONFIG['CACHE_SECONDS'], show_spinner=False)
def fetch_market_data(refresh_bucket=None):
    """Fetch one consistent full adjusted snapshot; never splice vintages.
    每5分钟缓存键更新；整批获取复权行情，不拼接不同版本，失败由页面明确回退。
    """
    raw = yahoo_download(TICKERS, start=USER_CONFIG['START_DATE'])
    raw = normalize_raw(completed_market_rows(normalize_raw(raw)))
    if raw.empty:
        raise ValueError('没有已收盘的有效行情')
    anchor = raw[('Close', 'QQQ')].last_valid_index()
    for field, ticker in [('Close', t) for t in TICKERS] + [('Volume', 'IPO')]:
        if raw[(field, ticker)].last_valid_index() < anchor:
            raise ValueError(f'{ticker}/{field} 最新行情落后于QQQ，拒绝把旧数据标为最新')
    saved = newest_backup()
    if saved is not None:
        old, _ = saved
        for field, ticker in [('Close', t) for t in TICKERS] + [('Volume', 'IPO')]:
            lost = old[(field, ticker)].dropna().index.difference(raw[(field, ticker)].dropna().index)
            if len(lost):
                raise ValueError(f'在线响应缺少已保存的 {ticker}/{field} 历史记录（{len(lost)} 条）；不拼接新旧复权价格')
    raw.attrs['retrieved_at_utc'] = datetime.now(timezone.utc).isoformat()
    note = ''
    if USER_CONFIG['SAVE_LOCAL_BACKUP']:
        try:
            save_snapshot(raw)
        except OSError as exc:
            note = f'在线行情已获取，但本地备份写入失败：{exc}。请下载备份。'
    return raw, note


