def embedded_market():
    """Validate the frozen snapshot before use / 使用前校验固定行情。"""
    content = base64.b64decode(EMBEDDED_MARKET_B64)
    if hashlib.sha256(content).hexdigest() != PREVIEW_EVIDENCE['market_sha256']:
        raise ValueError('内置行情快照哈希不符')
    return read_backup(content)


def published_reference():
    body = zlib.decompress(base64.b64decode(EMBEDDED_REFERENCE_B64))
    if hashlib.sha256(body).hexdigest() != PREVIEW_EVIDENCE['reference_compact_sha256']:
        raise ValueError('内置美投参考快照哈希不符')
    payload = json.loads(body)
    series = {}
    for key, entries in payload['points'].items():
        dates = pd.to_datetime([int(x[0]) for x in entries], unit='ms', utc=True)
        dates = dates.tz_convert('America/New_York').tz_localize(None).normalize().as_unit('ns')
        values = pd.Series([float(x[1]) for x in entries], index=dates, name=key).sort_index()
        if dates.has_duplicates or not np.isfinite(values).all() or not values.between(0, 100).all():
            raise ValueError('美投参考日期或分数校验失败')
        series[key] = values
    return pd.concat(series.values(), axis=1, sort=False).sort_index(), payload


def preview_comparisons(model, reference):
    """Exact shared observation dates; no interpolation / 只比较共同标签日期。"""
    records, pairs = [], {}
    for key in ['P1', 'P2', 'P3', 'P4', 'P5', 'P6', 'P7', 'total']:
        column = '完整指数' if key == 'total' else key
        ref_key = PREVIEW_REFERENCE_KEY.get(key, key)
        if column not in model or ref_key not in reference:
            continue
        joined = pd.concat([reference[ref_key].rename('美投发布值'), model[column].rename('自有模型')], axis=1, join='inner').dropna()
        pairs[key] = joined
        if joined.empty:
            continue
        error = joined['自有模型'] - joined['美投发布值']
        correlation = joined['美投发布值'].corr(joined['自有模型']) if len(joined) > 2 and joined.nunique().min() > 1 else np.nan
        records.append({'分项': PREVIEW_NAMES[key], '比较点数': len(joined),
            '平均绝对误差': float(error.abs().mean()), '相关系数': float(correlation),
            '最新共同日期': joined.index[-1].strftime('%Y-%m-%d'),
            '美投同日值': float(joined['美投发布值'].iloc[-1]), '模型同日值': float(joined['自有模型'].iloc[-1])})
    return pd.DataFrame(records), pairs


def preview_figure(model, reference, key, months):
    column = '完整指数' if key == 'total' else key
    local = model[column].dropna()
    published = reference[PREVIEW_REFERENCE_KEY.get(key, key)].dropna()
    end = max(local.index[-1], published.index[-1])
    start = min(published.index[0], local.index[0]) if months is None else end - pd.DateOffset(months=months)
    local = local.loc[start:end]; published = published.loc[start:end]
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=local.index, y=local, name='自有代理模型（含人工 +15 总分修正）' if key == 'total' else {**FACTOR_NAMES, **NEW_FACTOR_NAMES}.get(key, key) if 'P7' in model else FACTOR_NAMES[key],
        mode='lines', connectgaps=False, line=dict(color='#f0a25b', width=2)))
    fig.add_trace(go.Scatter(x=published.index, y=published, name='美投已发布参考点', mode='markers',
        marker=dict(color='#48cfb5', size=7), hovertemplate='%{x|%Y-%m-%d}<br>美投发布：%{y}<extra></extra>'))
    layout = dark_layout(height=450, y_range=[0, 100], y_title='分数')
    layout.update(showlegend=True, legend=dict(orientation='h', y=1.12), margin=dict(l=12, r=12, t=60, b=15))
    fig.update_layout(**layout)
    return fig


