# ============================================================
# 持仓基金对比：银华海外数字经济(016701) vs QQQ；建信新兴市场优选(539002) vs 费城半导体
# 基金用天天基金公布的人民币净值与日增长率（含分红再投资）；基准按 USD/CNY 换算为人民币。
# QDII 当日净值对应海外前一交易日收盘，默认把基金日期 T 对齐到 T 之前最近的美股收盘。
# ============================================================
HOLDINGS = [
    {"code": "016701", "name": "银华海外数字经济量化选股混合(QDII)A", "bench": "QQQ",
     "bench_name": "纳指100 ETF（QQQ，复权含分红）", "short": "银华 016701", "bench_short": "QQQ"},
    {"code": "539002", "name": "建信新兴市场优选混合(QDII)A", "bench": "^SOX",
     "bench_name": "费城半导体指数（^SOX，价格指数）", "short": "建信 539002", "bench_short": "费城半导体"},
]
HOLDING_WINDOWS = [("近1周", pd.DateOffset(weeks=1)), ("近1月", pd.DateOffset(months=1)),
                   ("近3月", pd.DateOffset(months=3)), ("近6月", pd.DateOffset(months=6)),
                   ("近1年", pd.DateOffset(years=1)), ("近1.5年", pd.DateOffset(months=18)),
                   ("近3年", pd.DateOffset(years=3)), ("成立以来", None)]
ROLLING_HORIZONS = [("1个月", 21), ("3个月", 63), ("6个月", 126), ("1年", 250)]


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_holding_market(refresh_bucket=None):
    tickers = sorted({h["bench"] for h in HOLDINGS} | {"CNY=X"})
    raw = yahoo_download(tickers, start="2014-01-01")
    if raw is None or raw.empty or "Close" not in raw:
        raise ValueError("未获得基准行情。")
    close = raw["Close"].copy()
    close.index = pd.to_datetime(close.index).tz_localize(None).normalize()
    close = close.loc[~close.index.duplicated()].sort_index()
    us_today = pd.Timestamp.now(tz="America/New_York").date()
    close = close.loc[close.index.date < us_today]  # 只用已收盘的美股交易日
    for t in tickers:
        if t not in close or close[t].dropna().empty:
            raise ValueError(f"{t} 行情缺失，未用其他标的替代。")
    return close, datetime.now(timezone.utc).isoformat()


def fund_wealth_full(nav):
    """用公布日增长率复利（含分红）；增长率缺失的日子用单位净值变化补，二者都缺则报错不补0。"""
    ret = nav["return"].copy()
    alt = nav["nav"].pct_change(fill_method=None)
    ret = ret.fillna(alt)
    ret.iloc[0] = 0.0
    if ret.iloc[1:].isna().any():
        bad = ret.iloc[1:][ret.iloc[1:].isna()].index[0]
        raise ValueError(f"{bad:%Y-%m-%d} 起净值与增长率均缺失，未以0收益填充。")
    return (1 + ret).cumprod()


def align_benchmark(fund_index, close, ticker, lag_days):
    """基金日期 T → 取 T−lag 天及以前最近的美股收盘；汇率取同一美股日期的 USD/CNY。"""
    usd = close[ticker].where(close[ticker] > 0).dropna()
    fx = close["CNY=X"].where(close["CNY=X"] > 0).dropna()
    keys = fund_index - pd.Timedelta(days=lag_days)
    us_date = pd.Series(usd.index, index=usd.index).reindex(keys, method="ffill")
    usd_val = usd.reindex(keys, method="ffill")
    fx_val = fx.reindex(us_date.values, method="ffill", tolerance=pd.Timedelta(days=5)).to_numpy()
    out = pd.DataFrame({"美股日期": us_date.to_numpy(), "基准美元": usd_val.to_numpy(), "USD/CNY": fx_val},
                       index=fund_index)
    out["基准人民币"] = out["基准美元"] * out["USD/CNY"]
    return out


def holding_frame(holding, close, lag_days):
    nav = fetch_fund_nav(holding["code"])
    wealth = fund_wealth_full(nav)
    bench = align_benchmark(wealth.index, close, holding["bench"], lag_days)
    frame = pd.concat([wealth.rename("基金"), nav["nav"].rename("单位净值"), bench], axis=1)
    frame = frame.dropna(subset=["基金", "基准人民币"])
    if len(frame) < 30:
        raise ValueError("基金与基准共同历史不足30个交易日。")
    return frame


def window_returns(frame):
    last = frame.index[-1]
    rows = []
    for label, offset in HOLDING_WINDOWS:
        start = frame.index[0] if offset is None else last - offset
        if start < frame.index[0]:
            rows.append({"区间": label, "起始日": None})
            continue
        base = frame.loc[:start].iloc[-1]
        end = frame.iloc[-1]
        days = (last - frame.loc[:start].index[-1]).days
        f = end["基金"] / base["基金"] - 1
        b = end["基准人民币"] / base["基准人民币"] - 1
        bu = end["基准美元"] / base["基准美元"] - 1
        row = {"区间": label, "起始日": f"{frame.loc[:start].index[-1]:%Y-%m-%d}", "基金%": f * 100,
               "基准(人民币)%": b * 100, "超额(百分点)": (f - b) * 100, "基准(美元)%": bu * 100}
        if days >= 360:
            row["基金年化%"] = ((1 + f) ** (365 / days) - 1) * 100
            row["基准年化%"] = ((1 + b) ** (365 / days) - 1) * 100
        rows.append(row)
    out = pd.DataFrame(rows)
    for col in out.columns:
        if col not in ("区间", "起始日"):
            out[col] = pd.to_numeric(out[col], errors="coerce")
    out["起始日"] = out["起始日"].fillna("—")
    return out


def rolling_average(frame):
    rows = []
    for label, h in ROLLING_HORIZONS:
        f = frame["基金"] / frame["基金"].shift(h) - 1
        b = frame["基准人民币"] / frame["基准人民币"].shift(h) - 1
        pair = pd.concat([f, b], axis=1).dropna()
        if len(pair) < 20:
            continue
        ex = pair.iloc[:, 0] - pair.iloc[:, 1]
        rows.append({"持有期": label, "样本窗口数": len(pair),
                     "基金平均%": pair.iloc[:, 0].mean() * 100, "基准平均%": pair.iloc[:, 1].mean() * 100,
                     "平均超额(百分点)": ex.mean() * 100, "超额中位数": ex.median() * 100,
                     "跑赢基准比例%": (ex > 0).mean() * 100, "基金正收益比例%": (pair.iloc[:, 0] > 0).mean() * 100})
    return pd.DataFrame(rows)


def risk_stats(frame, weeks):
    wk = frame[["基金", "基准人民币"]].resample("W-FRI").last().dropna().pct_change().dropna().tail(weeks)
    if len(wk) < 20:
        return None
    f, b = wk["基金"], wk["基准人民币"]
    lvl = frame[["基金", "基准人民币"]].loc[wk.index[0] - pd.Timedelta(days=7):]
    dd = lambda s: (s / s.cummax() - 1).min() * 100
    return {"周数": len(wk), "Beta": f.cov(b) / b.var(), "相关系数": f.corr(b),
            "基金年化波动%": f.std() * np.sqrt(52) * 100, "基准年化波动%": b.std() * np.sqrt(52) * 100,
            "跟踪误差%": (f - b).std() * np.sqrt(52) * 100,
            "基金最大回撤%": dd(lvl["基金"]), "基准最大回撤%": dd(lvl["基准人民币"])}


def render_holdings():
    page_header("持仓基金对比", "QDII 基金 vs 对应美股基准 · 人民币口径")
    st.sidebar.header("⚙️ 基金对比设置")
    lag = st.sidebar.radio("日期对齐", [1, 0], format_func=lambda x: "QDII 净值对齐前一美股交易日（推荐）" if x else "同日对齐",
                           key="holding_lag")
    if st.sidebar.button("重新获取净值与行情", key="holding_refresh"):
        fetch_fund_nav.clear(); fetch_holding_market.clear()
    try:
        with st.spinner("获取基准与汇率…"):
            close, retrieved = fetch_holding_market(int(datetime.now(timezone.utc).timestamp() // 3600))
    except Exception as exc:
        st.error(f"基准行情获取失败：{exc}"); return
    stamp = pd.Timestamp(retrieved).tz_convert("Asia/Tokyo")
    fx_last = close["CNY=X"].dropna()
    st.caption(f"基准与汇率来自 Yahoo Finance，{stamp:%Y-%m-%d %H:%M} 日本时间获取（缓存1小时）；"
               f"USD/CNY 最新 {fx_last.iloc[-1]:.4f}（{fx_last.index[-1]:%Y-%m-%d} 日线收盘，非实时）。"
               "基金净值来自天天基金公开数据（缓存6小时）。")
    frames = {}
    cards = st.columns(len(HOLDINGS))
    for holding, card in zip(HOLDINGS, cards):
        try:
            with st.spinner(f"获取 {holding['short']} 净值…"):
                frames[holding["code"]] = holding_frame(holding, close, lag)
        except Exception as exc:
            card.error(f"{holding['short']}：{exc}"); continue
        frame = frames[holding["code"]]
        wr = window_returns(frame).set_index("区间")
        y1 = wr.loc["近1年"] if "近1年" in wr.index and pd.notna(wr.loc["近1年"].get("基金%")) else None
        m1 = wr.loc["近1月"]
        def pct(v):
            return "—" if v is None or pd.isna(v) else f'<b style="color:{up_down_color(v)}">{v:+.1f}%</b>'

        def pair(row, label):
            if row is None:
                return f'<div><span>{label}</span><b>—</b></div>'
            ex = row["超额(百分点)"]
            return (f'<div class="fundcell"><span>{label}</span>'
                    f'<p><i>基金</i>{pct(row["基金%"])}</p><p><i>基准</i>{pct(row["基准(人民币)%"])}</p>'
                    f'<p><i>超额</i><b style="color:{up_down_color(ex)}">{ex:+.1f}pp</b></p></div>')

        card.markdown(
            f"""<div class="hero-card">
              <div class="fund-title">{holding['name']}<small>{holding['code']}</small></div>
              <div class="hero-label" style="margin-top:4px">对比基准 · {holding['bench_name']}</div>
              <div class="hero-grid" style="margin-top:14px">
                <div><span>最新净值</span><b>{frame['单位净值'].iloc[-1]:.4f}</b></div>
                <div><span>净值日期</span><b style="font-size:1.05rem">{frame.index[-1]:%Y-%m-%d}</b></div>
                <div><span>对齐美股收盘</span><b style="font-size:1.05rem">{pd.Timestamp(frame['美股日期'].iloc[-1]):%Y-%m-%d}</b></div>
              </div>
              <div class="hero-grid" style="margin-top:12px;grid-template-columns:1fr 1fr">
                {pair(m1, "近1个月")}{pair(y1, "近1年")}
              </div></div>""", unsafe_allow_html=True)
    if not frames:
        return
    tabs = st.tabs([h["short"] + " vs " + h["bench_short"] for h in HOLDINGS if h["code"] in frames])
    for tab, holding in zip(tabs, [h for h in HOLDINGS if h["code"] in frames]):
        frame = frames[holding["code"]]
        with tab:
            st.markdown("#### 区间收益（短期 → 长期）")
            st.dataframe(window_returns(frame), hide_index=True, width="stretch", column_config={
                c: st.column_config.NumberColumn(c, format="%+.2f") for c in
                ["基金%", "基准(人民币)%", "超额(百分点)", "基准(美元)%", "基金年化%", "基准年化%"]})
            st.caption("区间收益 = 最新值 ÷ 起始日（含当日之前最近一个净值日）的值 − 1；满1年的区间另列年化。"
                       "基准(人民币) = 美股基准 × 同一美股交易日的 USD/CNY；基准(美元)仅供参考。")
            st.markdown("#### 平均表现：全部历史的滚动持有期")
            st.dataframe(rolling_average(frame), hide_index=True, width="stretch", column_config={
                c: st.column_config.NumberColumn(c, format="%.2f") for c in
                ["基金平均%", "基准平均%", "平均超额(百分点)", "超额中位数", "跑赢基准比例%", "基金正收益比例%"]})
            st.caption(f"在 {frame.index[0]:%Y-%m-%d} 至 {frame.index[-1]:%Y-%m-%d} 的共同历史上，"
                       "把每个净值日都当作起点，统计持有对应天数（按基金净值日计）的收益平均值。窗口相互重叠，不是独立样本。")
            choice = st.radio("图表区间", ["近3月", "近6月", "近1年", "近1.5年", "近3年", "成立以来"], index=2,
                              horizontal=True, key=f"hold_range_{holding['code']}")
            offset = dict(HOLDING_WINDOWS)[choice]
            start = frame.index[0] if offset is None else frame.index[-1] - offset
            view = frame.loc[start:]
            norm = view[["基金", "基准人民币", "基准美元"]] / view[["基金", "基准人民币", "基准美元"]].iloc[0] * 100 - 100
            fig = go.Figure()
            fig.add_trace(go.Scatter(x=norm.index, y=norm["基金"], name=holding["short"], line=dict(color="#FF9F0A", width=2.4)))
            fig.add_trace(go.Scatter(x=norm.index, y=norm["基准人民币"], name=holding["bench_short"] + "（人民币）",
                                     line=dict(color=C_BLUE, width=2)))
            fig.add_trace(go.Scatter(x=norm.index, y=norm["基准美元"], name=holding["bench_short"] + "（美元）",
                                     line=dict(color=C_MUTED, width=1.3, dash="dot")))
            layout = dark_layout(height=440, y_title="累计收益 (%)", title_text=f"累计收益对比 · {choice}")
            layout.update(showlegend=True, legend=dict(orientation="h", y=1.1, x=1, xanchor="right", font=dict(size=12, color=C_MUTED)),
                          margin=dict(l=8, r=8, t=56, b=8))
            fig.update_layout(**layout)
            st.plotly_chart(fig, width="stretch")
            ex = (frame["基金"] / frame["基金"].shift(63) - frame["基准人民币"] / frame["基准人民币"].shift(63)) * 100
            exv = ex.loc[start:]
            fig2 = go.Figure(go.Scatter(x=exv.index, y=exv, fill="tozeroy", line=dict(color="#63E6BE", width=1.6),
                                        name="滚动3个月超额"))
            fig2.add_hline(y=0, line=dict(color=C_MUTED, width=1))
            fig2.update_layout(**dark_layout(height=280, y_title="百分点", title_text="滚动3个月超额收益（基金 − 基准人民币）"))
            st.plotly_chart(fig2, width="stretch")
            st.markdown("#### 风险与 Beta")
            rs = [dict(窗口=label, **stats) for label, w in [("近1年", 52), ("近3年", 156)]
                  if (stats := risk_stats(frame, w))]
            if rs:
                st.dataframe(pd.DataFrame(rs).round(3), hide_index=True, width="stretch")
            st.caption("Beta、相关系数、波动与跟踪误差用周五周收益（人民币口径、按上方日期对齐），回归窗口为最近52周与156周；"
                       "最大回撤为同一窗口内的累计净值路径。")
    st.caption("说明：QDII 基金 T 日净值一般反映海外 T−1 日收盘，因此默认把基金日期对齐到前一美股交易日；"
               "基金净值已扣除管理费等费用，基准不含费用。历史表现不代表未来收益。")


